import { HugeiconsIcon } from "@hugeicons/react";
import Search01Icon from "@hugeicons/core-free-icons/Search01Icon";

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { Input } from "@/registry/erbium/ui/input";

export default function ButtonGroupInput() {
  return (
    <ButtonGroup>
      <Input placeholder="Search..." />
      <Button variant="outline" aria-label="Search">
        <HugeiconsIcon icon={Search01Icon} />
      </Button>
    </ButtonGroup>
  );
}

import ExampleButtonGroupInput from "../examples/button-group-input";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleButtonGroupInput />
  </div>
);

export default Example;
